mapper.select:
SELECT reveal.ID id, reveal.REP_ID repId, reveal.REPORT_NAME reportName, reveal.REPORT_CATEGORY reportCategory, reveal.PROD_NAME prodName, reveal.PRODID prodid, reveal.END_DATE endDate, reveal.START_DATE startDate, reveal.SYS_FILENAME sysFilename, reveal.SYS_FILEPATH sysFilepath, reveal.SYS_FILENAME_DATE sysFilenameDate, reveal.FILEPATH filepath, reveal.TIME time, reveal.FILENAME filename, reveal.CONFIRM_STATUS confirmStatus, reveal.CONFIRM_USER confirmUser, reveal.CONFIRM_DATE confirmDate, reveal.REVEAL_STATUS revealStatus, reveal.REVEAL_DATE revealDate, reveal.REVEAL_USER revealUser, reveal.IS_REVEAL isReveal, reveal.IS_CONFIRM isConfirm, reveal.DETAIL detail, reveal.REVEAL_CHANNEL revealChannel, reveal.STATUS status, reveal.REVEAL_END_DATE revealEndDate, dsa.AGENCY_NAME saleAgency FROM REP_REVEAL reveal left join REP_PROD_INFO info on reveal.PRODID=info.PROD_ID LEFT JOIN DIS_PROD_AGENCY dpa on dpa.PROD_ID = nvl(info.P_PROD_ID,info.PROD_ID) LEFT JOIN DIS_SALE_AGENCY dsa on dsa.SEQUENCE_NO = dpa.AGENCY_ID WHERE 1=1 and dsa.AGENCY_NAME is not null
AND reveal.id in
#{item}
